import pandas as pd

def run(tables, report):
    df = tables["rt001"]
    # preserve identifiers; only coerce type
    psu_num = pd.to_numeric(df["psu"], errors="coerce")
    df["__derived.psu_int__"] = psu_num.round().astype("Int64")
    report["GEO-psu_int"] = {
        "n_total": int(len(df)),
        "n_nonnull": int(df["__derived.psu_int__"].notna().sum()),
    }

